import asyncio
import time

from fastapi import FastAPI

app = FastAPI(title="First API")


@app.get("/")
def root() -> dict:
    return {"message": "Hello from FastAPI"}


@app.get("/health")
def health() -> dict:
    return {"status": "ok"}


# TODO: add a GET /version endpoint that returns {"version": "0.1.0"}


@app.get("/wait/sync")
def wait_sync() -> dict:
    """A plain def endpoint: FastAPI runs it in a thread pool, so blocking here is safe."""
    time.sleep(1)
    return {"waited": 1}


@app.get("/wait/async")
async def wait_async() -> dict:
    """An async endpoint that awaits: the event loop serves other requests meanwhile."""
    await asyncio.sleep(1)
    return {"waited": 1}


@app.get("/wait/blocking")
async def wait_blocking() -> dict:
    """The classic mistake: a blocking call inside async def stops the whole event loop."""
    time.sleep(1)
    return {"waited": 1}

