    done: bool | None = None,
    priority: Annotated[int | None, Query(ge=1, le=3)] = None,
    limit: Annotated[int, Query(ge=1, le=100)] = 10,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Task]:
    """List tasks, optionally only done or open ones, or only one priority."""
    found = [
        task
        for task in data.TASKS.values()
        if (done is None or task.done == done) and (priority is None or task.priority == priority)
    ]
    return found[offset : offset + limit]


@router.get("/{task_id}")
def read_task(task_id: TaskId) -> Task:
    """One task, by its ID."""
    return get_or_404(task_id)


@router.post("", status_code=201)
def create_task(task: TaskCreate) -> Task:
    """Create a task. The server chooses its ID."""
    # TODO 4: make a TaskInDB from the validated task, with a new ID (data.new_id()) and
    #        created_by="api", store it in data.TASKS and return it
    raise NotImplementedError


@router.put("/{task_id}")
def replace_task(task_id: TaskId, task: TaskCreate) -> Task:
    """Replace a task completely; done and created_by are kept."""
    current = get_or_404(task_id)
    stored = TaskInDB(id=task_id, done=current.done, created_by=current.created_by, **task.model_dump())
    data.TASKS[task_id] = stored
    return stored


@router.patch("/{task_id}")
def update_task(task_id: TaskId, changes: TaskUpdate) -> Task:
    """Change only the fields that are sent."""
    current = get_or_404(task_id)
    # TODO 5: apply only the fields the client actually sent: changes.model_dump(exclude_unset=True)
    #        passed to current.model_copy(update=...). Store the result and return it.
    raise NotImplementedError


@router.delete("/{task_id}", status_code=204)
def delete_task(task_id: TaskId) -> None:
    """Delete a task."""
    get_or_404(task_id)
    del data.TASKS[task_id]

