"""A pretend database. An in-memory store sits behind sessions that each request opens and closes,
the way a real database layer such as SQLAlchemy works, so the endpoints never touch storage directly."""

import logging
from collections.abc import Iterator

from app.models import TaskCreate, TaskInDB, TaskUpdate

log = logging.getLogger("app.db")

SEED = [
    {"id": 1, "title": "Write the release notes", "priority": 2, "due": "2025-07-01"},
    {"id": 2, "title": "Review the API design", "priority": 1, "done": True},
    {"id": 3, "title": "Fix the login bug", "priority": 1,
     "checklist": [{"text": "Reproduce it", "done": True}, {"text": "Write a test"}]},
    {"id": 4, "title": "Update the dependencies", "priority": 3},
]


class Store:
    """The data itself; in a real application, the database server."""

    def __init__(self) -> None:
        self.tasks: dict[int, TaskInDB] = {}
        self.next_id = 1
        self.reset()

    def reset(self) -> None:
        self.tasks = {item["id"]: TaskInDB(**item) for item in SEED}
        self.next_id = max(self.tasks) + 1


STORE = Store()


class Session:
    """One unit of work against a store. It must be closed when the request is done."""

    opened = 0  # how many sessions have been opened in this process
    open_now = 0  # how many are open at this moment

    def __init__(self, store: Store) -> None:
        self.store = store
        Session.opened += 1
        Session.open_now += 1
        self.number = Session.opened
        log.info("session %d opened", self.number)

    def close(self) -> None:
        Session.open_now -= 1
        log.info("session %d closed", self.number)

    def list(self, done: bool | None = None, priority: int | None = None) -> list[TaskInDB]:
        return [
            task
            for task in self.store.tasks.values()
            if (done is None or task.done == done) and (priority is None or task.priority == priority)
        ]

    def get(self, task_id: int) -> TaskInDB | None:
        return self.store.tasks.get(task_id)

    def add(self, task: TaskCreate, created_by: str) -> TaskInDB:
        stored = TaskInDB(id=self.store.next_id, created_by=created_by, **task.model_dump())
        self.store.tasks[stored.id] = stored
        self.store.next_id += 1
        return stored

    def replace(self, current: TaskInDB, task: TaskCreate) -> TaskInDB:
        stored = TaskInDB(
            id=current.id, done=current.done, created_by=current.created_by, **task.model_dump()
        )
        self.store.tasks[current.id] = stored
        return stored

    def update(self, current: TaskInDB, changes: TaskUpdate) -> TaskInDB:
        stored = current.model_copy(update=changes.model_dump(exclude_unset=True))
        self.store.tasks[current.id] = stored
        return stored

    def delete(self, current: TaskInDB) -> None:
        del self.store.tasks[current.id]


def get_session() -> Iterator[Session]:
    """A dependency: open a session for the request, and always close it afterwards."""
    # TODO 1: open a Session on STORE, yield it, and close it in a finally block, so it's closed
    #        even when the endpoint raises an error
    raise NotImplementedError

