@dataclass
class Page:
    limit: int
    offset: int


def pagination(
    limit: Annotated[int, Query(ge=1, le=100, description="How many tasks to return")] = 10,
    offset: Annotated[int, Query(ge=0, description="How many tasks to skip")] = 0,
) -> Page:
    """Shared paging parameters for any endpoint that returns a list."""
    return Page(limit, offset)


PageDep = Annotated[Page, Depends(pagination)]


@dataclass
class ApiUser:
    email: str
    can_write: bool


# Demo keys only. A real service keeps keys out of the code, in configuration or a secrets store.
API_KEYS = {
    "dev-writer-key": ApiUser("ana@example.com", can_write=True),
    "dev-reader-key": ApiUser("bilal@example.com", can_write=False),
}

api_key_header = APIKeyHeader(name="X-API-Key", auto_error=False)


def current_user(api_key: Annotated[str | None, Depends(api_key_header)]) -> ApiUser:
    """Who is calling: 401 if the X-API-Key header is missing or unknown."""
    user = API_KEYS.get(api_key) if api_key else None
    if user is None:
        raise HTTPException(
            status_code=401,
            detail="A valid X-API-Key header is required",
            headers={"WWW-Authenticate": "ApiKey"},
        )
    return user


def writer(user: Annotated[ApiUser, Depends(current_user)]) -> ApiUser:
    """A caller who may change tasks: 403 for a valid key without write access."""
    # TODO 2: raise HTTPException 403 with the detail "This API key can't change tasks" when
    #        user.can_write is False; otherwise return the user
    return user


Writer = Annotated[ApiUser, Depends(writer)]

