from datetime import date
from typing import Annotated

from pydantic import BaseModel, ConfigDict, Field, field_validator

Title = Annotated[str, Field(min_length=1, max_length=200, examples=["Write the release notes"])]
Priority = Annotated[int, Field(ge=1, le=3, description="1 is the most urgent, 3 the least")]


def clean_title(value: str | None) -> str | None:
    if value is not None:
        value = value.strip()
        if not value:
            raise ValueError("title can't be blank")
    return value


class ChecklistItem(BaseModel):
    text: Annotated[str, Field(min_length=1, max_length=100)]
    done: bool = False


class TaskCreate(BaseModel):
    """What a client sends to create or replace a task."""

    model_config = ConfigDict(extra="forbid")

    title: Title
    priority: Priority = 2
    due: date | None = None
    checklist: list[ChecklistItem] = []

    @field_validator("title")
    @classmethod
    def title_is_not_blank(cls, value: str) -> str:
        return clean_title(value)


class TaskUpdate(BaseModel):
    """A partial update: send only the fields to change."""

    model_config = ConfigDict(extra="forbid")

    title: Title | None = None
    priority: Priority | None = None
    due: date | None = None
    done: bool | None = None

    @field_validator("title")
    @classmethod
    def title_is_not_blank(cls, value: str | None) -> str | None:
        return clean_title(value)


class Task(TaskCreate):
    """A task as the API returns it."""

    model_config = ConfigDict(extra="ignore")

    id: int
    done: bool = False


class TaskInDB(Task):
    """What the server stores: also who created the task, which the API never returns."""

    created_by: str = "seed"

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Path
from pydantic import BaseModel

from app.dependencies import DbSession, PageDep, Writer, writer
from app.models import Task, TaskCreate, TaskInDB, TaskUpdate


class Message(BaseModel):
    detail: str


NOT_FOUND = {404: {"model": Message, "description": "No task has this ID"}}
NEEDS_KEY = {
    401: {"model": Message, "description": "The X-API-Key header is missing or unknown"},
    403: {"model": Message, "description": "This API key can only read"},
}

router = APIRouter(prefix="/tasks", tags=["tasks"])
TaskId = Annotated[int, Path(ge=1)]


def task_or_404(task_id: TaskId, session: DbSession) -> TaskInDB:
    """A dependency that finds the task in the path, or answers 404."""
    task = session.get(task_id)
    if task is None:
        raise HTTPException(status_code=404, detail="Task not found")
    return task


FoundTask = Annotated[TaskInDB, Depends(task_or_404)]


@router.get("", summary="List tasks")
def list_tasks(session: DbSession, page: PageDep, done: bool | None = None) -> list[Task]:
    """List tasks, optionally only done or open ones."""
    return session.list(done=done)[page.offset : page.offset + page.limit]


# TODO 2: document the 404 this route can return: add responses=NOT_FOUND and summary="Read a task"
@router.get("/{task_id}")
def read_task(task: FoundTask) -> Task:
    """One task, by its ID."""
    return task


@router.post("", status_code=201, summary="Create a task", responses=NEEDS_KEY)
def create_task(task: TaskCreate, user: Writer, session: DbSession) -> Task:
    """Create a task, recording who created it. The key is checked before a session opens."""
    return session.add(task, created_by=user.email)


@router.put("/{task_id}", dependencies=[Depends(writer)], summary="Replace a task",
            responses={**NOT_FOUND, **NEEDS_KEY})
def replace_task(current: FoundTask, task: TaskCreate, session: DbSession) -> Task:
    """Replace a task completely; done and created_by are kept."""
    return session.replace(current, task)


@router.patch("/{task_id}", dependencies=[Depends(writer)], summary="Update part of a task",
              responses={**NOT_FOUND, **NEEDS_KEY})
def update_task(current: FoundTask, changes: TaskUpdate, session: DbSession) -> Task:
    """Change only the fields that are sent."""
    return session.update(current, changes)


@router.delete("/{task_id}", status_code=204, dependencies=[Depends(writer)], summary="Delete a task",
               responses={**NOT_FOUND, **NEEDS_KEY})
def delete_task(current: FoundTask, session: DbSession) -> None:
    """Delete a task."""
    session.delete(current)



# TODO 3: mark this old route as deprecated (deprecated=True), so the docs show it struck through
@router.get("/open/all", summary="List open tasks")
def list_open_tasks(session: DbSession, page: PageDep) -> list[Task]:
    """Use GET /tasks?done=false instead."""
    return session.list(done=False)[page.offset : page.offset + page.limit]
